def parse_json(s: str) -> object:
    """
    A simple recursive descent parser to parse a JSON string into corresponding Python objects
    (dict, list, str, int/float, bool, None) using a state machine approach.
    """

    def parse_value(index: int) -> tuple:
        char = s[index]
        if char == '"':
            return parse_string(index)
        elif char.isdigit() or char == '-':
            return parse_number(index)
        elif s[index:index + 4] == 'true':
            return True, index + 4
        elif s[index:index + 5] == 'false':
            return False, index + 5
        elif s[index:index + 4] == 'null':
            return None, index + 4
        elif char == '[':
            return parse_array(index)
        elif char == '{':
            return parse_object(index)
        raise ValueError("Invalid JSON input")

    def parse_string(index: int) -> tuple:
        end_index = index + 1
        result = []
        while end_index < len(s):
            if s[end_index] == '"':
                return ''.join(result), end_index + 1
            elif s[end_index] == '\\':
                end_index += 1
                if end_index < len(s):
                    result.append(s[end_index])
            else:
                result.append(s[end_index])
            end_index += 1
        raise ValueError("Unterminated string")

    def parse_number(index: int) -> tuple:
        end_index = index
        while end_index < len(s) and (s[end_index].isdigit() or s[end_index] in ['-', '.', 'e', 'E']):
            end_index += 1
        num_str = s[index:end_index]
        if '.' in num_str or 'e' in num_str or 'E' in num_str:
            return float(num_str), end_index
        else:
            return int(num_str), end_index

    def parse_array(index: int) -> tuple:
        index += 1
        arr = []
        while index < len(s):
            char = s[index]
            if char == ']':
                return arr, index + 1
            value, index = parse_value(index)
            arr.append(value)
            char = s[index]
            if char == ',':
                index += 1
                continue
            elif char == ']':
                return arr, index + 1
            raise ValueError("Invalid array syntax")
        raise ValueError("Unterminated array")

    def parse_object(index: int) -> tuple:
        index += 1
        obj = {}
        while index < len(s):
            char = s[index]
            if char == '}':
                return obj, index + 1
            key, index = parse_string(index)
            if s[index] != ':':
                raise ValueError("Missing colon in object")
            index += 1
            value, index = parse_value(index)
            obj[key] = value
            char = s[index]
            if char == ',':
                index += 1
                continue
            elif char == '}':
                return obj, index + 1
            raise ValueError("Invalid object syntax")
        raise ValueError("Unterminated object")

    result, next_index = parse_value(0)
    if next_index != len(s):
        raise ValueError("Extra data after JSON input")
    return result

def parse_json(s: str) -> object:
    """
    A state machine parser to interpret JSON strings, managing state transitions
    based on characters read and using a stack to handle nested structures like arrays and objects.
    """

    class ParserState:
        def __init__(self, s):
            self.s = s
            self.index = 0
            self.stack = []
            self.result = None

        def next_char(self):
            if self.index < len(self.s):
                return self.s[self.index]
            return None

        def consume_char(self):
            char = self.next_char()
            if char is not None:
                self.index += 1
            return char

        def parse(self):
            self.result = self.parse_value()
            if self.index < len(self.s):
                raise ValueError("Extra data after JSON input")
            return self.result

        def parse_value(self):
            char = self.next_char()
            if char == '"':
                return self.parse_string()
            elif char.isdigit() or char == '-':
                return self.parse_number()
            elif self.s[self.index:self.index + 4] == 'true':
                self.index += 4
                return True
            elif self.s[self.index:self.index + 5] == 'false':
                self.index += 5
                return False
            elif self.s[self.index:self.index + 4] == 'null':
                self.index += 4
                return None
            elif char == '[':
                return self.parse_array()
            elif char == '{':
                return self.parse_object()
            raise ValueError("Invalid JSON input")

        def parse_string(self):
            self.consume_char()  # consume opening quote
            start_index = self.index
            result = []
            while self.index < len(self.s):
                char = self.consume_char()
                if char == '"':
                    return ''.join(result)
                elif char == '\\':
                    escaped_char = self.consume_char()
                    if escaped_char in ['"', '\\', '/', 'b', 'f', 'n', 'r', 't']:
                        result.append(self.unescape(escaped_char))
                    else:
                        raise ValueError("Invalid escape character")
                else:
                    result.append(char)
            raise ValueError("Unterminated string")

        def unescape(self, char):
            if char == 'b': return '\b'
            if char == 'f': return '\f'
            if char == 'n': return '\n'
            if char == 'r': return '\r'
            if char == 't': return '\t'
            return char

        def parse_number(self):
            start_index = self.index
            while self.index < len(self.s) and self.s[self.index] in "-0123456789.eE":
                self.index += 1
            number_str = self.s[start_index:self.index]
            if '.' in number_str or 'e' in number_str or 'E' in number_str:
                return float(number_str)
            return int(number_str)

        def parse_array(self):
            self.consume_char()  # consume opening bracket
            array = []
            while True:
                char = self.next_char()
                if char == ']':
                    self.consume_char()  # consume closing bracket
                    return array
                value = self.parse_value()
                array.append(value)
                char = self.next_char()
                if char == ',':
                    self.consume_char()
                elif char == ']':
                    self.consume_char()  # consume closing bracket
                    return array
                else:
                    raise ValueError("Invalid array syntax")

        def parse_object(self):
            self.consume_char()  # consume opening brace
            obj = {}
            while True:
                char = self.next_char()
                if char == '}':
                    self.consume_char()  # consume closing brace
                    return obj
                key = self.parse_string()
                if self.consume_char() != ':':
                    raise ValueError("Missing colon after key in object")
                value = self.parse_value()
                obj[key] = value
                char = self.next_char()
                if char == ',':
                    self.consume_char()
                elif char == '}':
                    self.consume_char()  # consume closing brace
                    return obj
                else:
                    raise ValueError("Invalid object syntax")

    parser = ParserState(s)
    return parser.parse()

