    """
    A recursive descent parser for JSON that makes use of function calls to parse 
    different elements, leveraging string traversal for structured data extraction.
    """

    def parse_value(index):
        char = s[index]

        if char == '"':
            return parse_string(index)
        elif char.isdigit() or char == '-':
            return parse_number(index)
        elif s.startswith('true', index):
            return True, index + 4
        elif s.startswith('false', index):
            return False, index + 5
        elif s.startswith('null', index):
            return None, index + 4
        elif char == '[':
            return parse_array(index)
        elif char == '{':
            return parse_object(index)
        raise ValueError("Invalid JSON input")

    def parse_string(index):
        index += 1  # skip opening quote
        result = []

        while index < len(s):
            char = s[index]
            if char == '"':
                return ''.join(result), index + 1
            elif char == '\\':
                index += 1  # skip backslash
                if index < len(s):
                    escaped = s[index]
                    if escaped in '"\\/bfnrt':
                        result.append(unescape(escaped))
                    else:
                        raise ValueError("Invalid escape character")
            else:
                result.append(char)
            index += 1

        raise ValueError("Unterminated string")

    def unescape(char):
        escape_dict = {
            'b': '\b',
            'f': '\f',
            'n': '\n',
            'r': '\r',
            't': '\t',
            '"': '"',
            '\\': '\\',
            '/': '/'
        }
        return escape_dict.get(char, char)

    def parse_number(index):
        start = index
        if s[index] == '-':
            index += 1
        while index < len(s) and s[index].isdigit():
            index += 1
        if index < len(s) and s[index] in '.eE':
            index += 1
            if s[index - 1] == '.':
                while index < len(s) and s[index].isdigit():
                    index += 1
            if s[index - 1] in 'eE':
                if s[index] in '+-':
                    index += 1
                while index < len(s) and s[index].isdigit():
                    index += 1
        number_str = s[start:index]
        if '.' in number_str or 'e' in number_str or 'E' in number_str:
            return float(number_str), index
        else:
            return int(number_str), index

    def parse_array(index):
        index += 1  # skip opening bracket
        array = []

        while index < len(s):
            if s[index] == ']':
                return array, index + 1
            value, index = parse_value(index)
            array.append(value)
            if s[index] == ',':
                index += 1
            elif s[index] == ']':
                return array, index + 1
            else:
                raise ValueError("Invalid array syntax")
        raise ValueError("Unterminated array")

    def parse_object(index):
        index += 1  # skip opening brace
        obj = {}

        while index < len(s):
            if s[index] == '}':
                return obj, index + 1

            key, index = parse_string(index)
            if s[index] != ':':
                raise ValueError("Missing colon after key in object")
            index += 1  # skip colon
            value, index = parse_value(index)
            obj[key] = value

            if s[index] == ',':
                index += 1
            elif s[index] == '}':
                return obj, index + 1
            else:
                raise ValueError("Invalid object syntax")
        raise ValueError("Unterminated object")

    result, remaining_index = parse_value(0)
    if remaining_index < len(s):
        raise ValueError("Extra data after JSON input")

    return result

