    """
    A state machine-based parser for JSON that processes the input string in a single
    pass while maintaining the current state. It builds the corresponding Python 
    objects using a stack for arrays and dictionaries without recursion.
    """

    stack = []
    current = None
    index = 0
    state = 'value'
    buffer = ""

    while index < len(s):
        char = s[index]

        if state == 'value':
            if char.isspace():
                index += 1
                continue
            elif char == '{':
                new_obj = {}
                if current is not None:
