                        current.append(new_obj)
                    else:
                        raise ValueError("Invalid state: object expected")
                current = new_obj
                stack.append(current)
                state = 'key'
            elif char == '[':
                new_array = []
                if current is not None:
                    if isinstance(current, list):
                        current.append(new_array)
                    else:
                        raise ValueError("Invalid state: array expected")
                current = new_array
                stack.append(current)
                state = 'value' 
            elif char == '"':
                buffer = ''
                state = 'string'
            elif char.isdigit() or char == '-':
                buffer += char
                state = 'number'
            elif s.startswith('true', index):
                if current is not None:
                    if isinstance(current, list):
                        current.append(True)
                    else:
                        raise ValueError("Invalid state: boolean expected")
