                current = False
                index += 5
            elif s.startswith('null', index):
                if current is not None:
                    if isinstance(current, list):
                        current.append(None)
                    else:
                        raise ValueError("Invalid state: null expected")
                current = None
                index += 4
            else:
                raise ValueError("Unexpected character")

        elif state == 'string':
            if char == '"':
                if current is not None and isinstance(current, dict):
                    current[buffer] = None
                    state = 'value'  
                elif isinstance(current, list):
                    current.append(buffer)
                buffer = ""
                state = 'value'
            elif char == '\\':
                index += 1
                if index < len(s):
                    escape_char = s[index]
                    escaped = {
                        'b': '\b', 'f': '\f', 'n': '\n', 'r': '\r', 't': '\t',
                        '"': '"', '\\': '\\', '/': '/'
                    }.get(escape_char, escape_char)
                    buffer += escaped
            else:
                buffer += char

        elif state == 'number':
            if char.isdigit() or char in '.-+eE':
                buffer += char
            else:
                if current is not None:
                    if isinstance(current, list):
                        current.append(float(buffer) if '.' in buffer or 'e' in buffer or 'E' in buffer else int(buffer))
                    else:
                        raise ValueError("Invalid state: number expected")
                current = None
                buffer = ""
                state = 'value'
                index -= 1  # go back one step for the next iteration

        if char == '}':
            if len(stack) == 0:
                raise ValueError("Unexpected closing brace")
            current = stack.pop()
            if isinstance(current, dict):
                if len(stack) > 0:
                    current = stack[-1]
                else:
                    return current

        elif char == ']':
            if len(stack) == 0:
                raise ValueError("Unexpected closing bracket")
            current = stack.pop()
            if isinstance(current, list):
                if len(stack) > 0:
                    current = stack[-1]
                else:
                    return current

        index += 1

    if state != 'value':
        raise ValueError("Invalid JSON input")

    return current if current is not None else None

def parse_json(s: str) -> object:
    """
    A recursive descent parser for JSON. This method uses a set of functions that 
    parse specific components of JSON (e.g., strings, numbers, objects, arrays). 
    The approach allows for a clean separation of parsing logic and handles nested 
    structures through recursion.
    """

    def parse_value(index):
        if index >= len(s):
            raise ValueError("Unexpected end of input")

        char = s[index]
        if char.isspace():
            return parse_value(index + 1)
        elif char == '"':
            return parse_string(index)
        elif char.isdigit() or (char == '-' and s[index + 1].isdigit()):
            return parse_number(index)
        elif s.startswith("true", index):
            return True, index + 4
        elif s.startswith("false", index):
            return False, index + 5
        elif s.startswith("null", index):
            return None, index + 4
        elif char == '{':
            return parse_object(index)
        elif char == '[':
            return parse_array(index)
        else:
            raise ValueError(f"Unexpected character: {char}")

    def parse_string(index):
        index += 1  # Skip opening quote
        output = ""
        while index < len(s):
            char = s[index]
            if char == '"':
                return output, index + 1  # Return next index after closing quote
            elif char == '\\':
                index += 1
                if index < len(s):
                    escape_char = s[index]
                    if escape_char == 'b': output += '\b'
                    elif escape_char == 'f': output += '\f'
                    elif escape_char == 'n': output += '\n'
                    elif escape_char == 'r': output += '\r'
                    elif escape_char == 't': output += '\t'
                    elif escape_char in ['"', '\\', '/']: output += escape_char
            else:
                output += char
            index += 1
        raise ValueError("Unterminated string")

    def parse_number(index):
        start_index = index
        if s[index] == '-':
            index += 1
        while index < len(s) and (s[index].isdigit() or s[index] in '.eE+-'):
            index += 1
        number = s[start_index:index]
        return (float(number) if '.' in number or 'e' in number or 'E' in number else int(number)), index

    def parse_object(index):
        obj = {}
        index += 1  # Skip opening brace
        while index < len(s):
            index = skip_whitespace(index)
            if s[index] == '}':
                return obj, index + 1  # Return next index after closing brace
            key, index = parse_string(index)
            index = skip_whitespace(index)
            if s[index] != ':':
                raise ValueError("Expected ':' after key")
            index += 1  # Skip colon
            value, index = parse_value(index)
            obj[key] = value
            index = skip_whitespace(index)
            if s[index] == ',':
                index += 1  # Skip comma
            elif s[index] == '}':
                continue
            else:
                raise ValueError("Expected ',' or '}'")
        raise ValueError("Unterminated object")

    def parse_array(index):
        array = []
        index += 1  # Skip opening bracket
        while index < len(s):
            index = skip_whitespace(index)
            if s[index] == ']':
                return array, index + 1  # Return next index after closing bracket
            value, index = parse_value(index)
            array.append(value)
            index = skip_whitespace(index)
            if s[index] == ',':
                index += 1  # Skip comma
            elif s[index] == ']':
                continue
            else:
                raise ValueError("Expected ',' or ']'")
        raise ValueError("Unterminated array")

    def skip_whitespace(index):
        while index < len(s) and s[index].isspace():
            index += 1
        return index

    result, index = parse_value(0)
    if index < len(s):
        raise ValueError("Extra data after JSON input")

    return result
